mapper.select:
SELECT c.id, c.enterprise_id, c.name, c.kind, c.status, c.revision, c.created_at, c.updated_at, (SELECT COUNT(*) FROM resource r WHERE r.enterprise_id = c.enterprise_id AND r.status = 'active' AND r.deleted_at IS NULL AND r.kind IN ('plugin', 'data') AND ( EXISTS (SELECT 1 FROM resource_draft d WHERE d.enterprise_id = r.enterprise_id AND d.resource_id = r.id AND (JSON_UNQUOTE(JSON_EXTRACT(d.config_json, '$.credentialId')) = c.id OR JSON_CONTAINS(LOWER(JSON_EXTRACT(d.config_json, '$.sources[*].credentialId')), JSON_QUOTE(LOWER(c.id))))) OR EXISTS (SELECT 1 FROM resource_version v WHERE v.enterprise_id = r.enterprise_id AND v.resource_id = r.id AND v.status = 'available' AND (JSON_UNQUOTE(JSON_EXTRACT(v.config_json, '$.credentialId')) = c.id OR JSON_CONTAINS(LOWER(JSON_EXTRACT(v.config_json, '$.sources[*].credentialId')), JSON_QUOTE(LOWER(c.id))))))) AS reference_count FROM credential c WHERE c.enterprise_id = #{enterprise}
AND (c.created_at < #{cursor.time} OR (c.created_at = #{cursor.time} AND c.id < #{cursor.id}))
ORDER BY c.created_at DESC, c.id DESC LIMIT #{limit}
